import sqlite3
import functools

def decorator(func):

    @functools.wraps(func)
    def wrapper(*args, **kwargs):

        conn = sqlite3.connect(filename)
        cursor = conn.cursor()
        cursor.execute(f"SELECT output FROM {func_name} WHERE args = ? AND kwargs = ?", (str(args), str(kwargs)))
        result = cursor.fetchone()
        if result:
            return eval(result[0])
        else:
            output = func(*args, **kwargs)
            cursor.execute(f"CREATE TABLE IF NOT EXISTS {func_name} (args TEXT, kwargs TEXT, output TEXT)")
            cursor.execute(f"INSERT INTO {func_name} VALUES (?, ?, ?)", (str(args), str(kwargs), str(output)))
            conn.commit()
            conn.close()
            return output

    return wrapper

return decorator

