            kwargs_string = str(kwargs)
            cursor.execute(
                f"SELECT result FROM cache WHERE func_name = '{func_name}' AND args = '{args_string}' AND kwargs = '{kwargs_string}'"
            )
            result = cursor.fetchone()
            if result:
                return eval(result[0])
            else:
                result = func(*args, **kwargs)
                cursor.execute(
                    f"INSERT INTO cache VALUES ('{func_name}', '{args_string}', '{kwargs_string}', '{result}')"
                )
                conn.commit()
                return result

    return wrapper

return decorator

import sqlite3
import functools

def decorator_memoize_to_sqlite(func):
    @functools.wraps(func)
    def memoize_wrapper(*args, **kwargs):
        conn = sqlite3.connect(filename)
        c = conn.cursor()
        c.execute(f"CREATE TABLE IF NOT EXISTS {func_name}(arg_1, arg_2, arg_3, arg_4, arg_5, result)")
        result = c.execute(f"SELECT result FROM {func_name} WHERE arg_1=? AND arg_2=? AND arg_3=? AND arg_4=? AND arg_5=?",
                           (str(args), str(kwargs), str(args), str(kwargs), str(args), str(kwargs))).fetchone()
        if result:
            return eval(result[0])
        else:
            result = func(*args, **kwargs)
            c.execute(f"INSERT INTO {func_name} VALUES (?, ?, ?, ?, ?, ?)",
                      (str(args), str(kwargs), str(args), str(kwargs), str(args), str(kwargs), str(result)))
            conn.commit()
            return result

    return memoize_wrapper

return decorator_memoize_to_sqlite

