import contextlib
import pyaoscx.utils.util as utils

@contextlib.contextmanager
def _optimize_dns_context(enable: bool) -> Any:

    # Get the current DNS optimization status
    current_dns_optimization_status = utils.get_dns_optimization()

    # If the current DNS optimization status is the same as the desired status, do nothing
    if current_dns_optimization_status == enable:
        yield

    # If the current DNS optimization status is different than the desired status, set the DNS optimization status to the desired status
    else:
        utils.set_dns_optimization(enable)
        yield
        utils.set_dns_optimization(False)

return _optimize_dns_context(enable)

