# This function is taken from https://github.com/facebookresearch/fvcore/blob/master/fvcore/nn/jit_handles.py
def get_jit_model_analysis(
    model: nn.Module, inputs: list, flatten_inputs: bool = False
) -> typing.Tuple[typing.DefaultDict[str, float], typing.List[str]]:
    """
    Given a model, the input and whether to flatten the input, compute the Gflops of the model.
    """
    assert isinstance(
        model, torch.nn.Module
    ), "Got {} while expecting torch.nn.Module".format(type(model))
    if flatten_inputs:
        assert isinstance(
            inputs, torch.Tensor
        ), "Got {} while expecting torch.Tensor".format(type(inputs))
    elif isinstance(inputs, list):
        assert all(
            [isinstance(i, torch.Tensor) for i in inputs]
        ), "Got {} while all expecting list[torch.Tensor]".format(
            [type(i) for i in inputs]
        )
    else:
        raise TypeError(
            "Got {} while expecting torch.Tensor or list[torch.Tensor]".format(
                type(inputs)
            )
        )

    # ignore some ops
    ignored_ops = get_ignored_ops()

    # execute the forward function
    with torch.no_grad():
        if flatten_inputs:
            outputs = model(inputs)
        else:
            outputs = model(inputs)

    # make a deep copy of the model
    model_copy = copy.deepcopy(model)

    # create a graph of the model using JIT
    jit_graph = torch._C._jit_pass_inline(
        model_copy.graph
    )  # pylint: disable=protected-access
    jit_graph = torch._C._jit_pass_remove

# To count the flops, we use jit tracing
# The code below is modified from jit.trace
trace, torch = get_trace(model, inputs)

# Now that we have the trace, we extract the information
# for each module.
# We rely on jit internal module to get this information
graph = trace.graph()
