# This is a helper function to extract the operator name from a node
def _get_operator_name(g, n):
    # Naming logic from `torch.jit._builtins._find_builtin`
    if n.kind() == "prim::PythonOp":
        return n.pyname()
    elif n.kind() == "prim::Constant":
        return n.kind()
    else:
        return n.kind() + "::" + n.snake_name()

# This is a helper function to extract the input dimension size
def _get_input_dims(g, n):
    input_dims = []
    for inp in n.inputs():
        if inp.isCompleteTensor():
            shape = inp.type().sizes()
            input_dims.append(shape)
    return input_dims

# This is a helper function to extract the output dimension size
def _get_output_dims(g, n):
    output_dims = []
    for out in n.outputs():
        if out.isCompleteTensor():
            shape = out.type().sizes()
            output_dims.append(shape)
    return output_dims

# This is a helper function to extract the parameters
def _get_parameters(g, n):
    params = {}
    for p in n.params():
        if p.isCompleteTensor():
            params[p.debugName()] = p.type().sizes()
    return params

